# Leak check for this public repo. Blocks pushes that contain private data.
#
# Runs from the local pre-push hook (.git/hooks/pre-push) and from
# .github/workflows/leak-check.yml. Works on Windows PowerShell 5.1 and PowerShell 7.
#
# What it looks for, in every text file of the revision being pushed:
#   EMAIL        any e-mail address that isn't on the allow list
#   PHONE_LK     Sri Lankan mobile numbers
#   NIC_OLD/NEW  Sri Lankan NIC numbers
#   SECRET       API keys, tokens, private keys
#   ENDPOINT     private backends and internal links (Apps Script, webhooks, Lark shares)
#   BLOB         claude.ai artifact asset links
#   DENY#n       private terms (company and project names). Only SHA-256 hashes of them are
#                stored here, in denylist.sha256, so this public repo never contains the terms.
#                The readable list lives in .git/leak-guard/denylist.txt, which is never pushed;
#                after editing it, run:  leak-check.ps1 -UpdateHashes
# Reviewed exceptions go in allow.txt.
param(
  [string]$Root = (Get-Location).Path,
  [string]$Rev,
  [string]$Messages,
  [string]$Git = $(if ($env:LEAK_GIT) { $env:LEAK_GIT } else { 'git' }),
  [switch]$UpdateHashes
)
$ErrorActionPreference = 'Stop'
try { [Console]::OutputEncoding = [Text.Encoding]::UTF8 } catch {}
$utf8 = New-Object System.Text.UTF8Encoding $false
$guard = Join-Path $Root '.github/leak-guard'
$hashFile = Join-Path $guard 'denylist.sha256'
$allowFile = Join-Path $guard 'allow.txt'
$plainFile = Join-Path $Root '.git/leak-guard/denylist.txt'
$sha = [Security.Cryptography.SHA256]::Create()
function Hash([string]$s) { [BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($s))).Replace('-', '').ToLowerInvariant() }
function Tokens([string]$s) { @(([regex]::Replace($s.ToLowerInvariant(), '[^\p{L}\p{N}]+', ' ')).Trim().Split(' ', [StringSplitOptions]::RemoveEmptyEntries)) }

if ($UpdateHashes) {
  if (-not (Test-Path $plainFile)) { throw "No local list at $plainFile" }
  $out = New-Object System.Collections.Generic.List[string]
  $out.Add('# SHA-256 of private terms (lower-cased, punctuation as spaces). Generated by leak-check.ps1 -UpdateHashes.')
  $id = 0
  foreach ($line in [IO.File]::ReadAllLines($plainFile, $utf8)) {
    $t = $line.Trim(); if (-not $t -or $t.StartsWith('#')) { continue }
    $tok = Tokens $t; if ($tok.Count -eq 0) { continue }
    $id++; $out.Add("$id $(Hash ($tok -join ' ')) $($tok.Count)")
  }
  [IO.File]::WriteAllLines($hashFile, $out, $utf8)
  Write-Host "Wrote $id hashed terms to $hashFile"
  exit 0
}

# ---------- load lists ----------
$deny = @{}; $sizes = @{}
if (Test-Path $hashFile) {
  foreach ($line in [IO.File]::ReadAllLines($hashFile, $utf8)) {
    if ($line -match '^(\d+)\s+([0-9a-f]{64})\s+(\d+)') { $deny[$Matches[2]] = $Matches[1]; $sizes[[int]$Matches[3]] = $true }
  }
}
$allow = @()
if (Test-Path $allowFile) {
  foreach ($line in [IO.File]::ReadAllLines($allowFile, $utf8)) {
    $t = $line.Trim(); if (-not $t -or $t.StartsWith('#')) { continue }
    $parts = $t -split '\s+', 3
    $allow += [pscustomobject]@{ glob = $parts[0]; rule = $parts[1]; value = $(if ($parts.Count -gt 2) { $parts[2] } else { $null }) }
  }
}
function Allowed([string]$path, [string]$rule, [string]$value) {
  foreach ($a in $allow) {
    if ($path -like $a.glob -and $rule -like $a.rule -and (-not $a.value -or $value -match $a.value)) { return $true }
  }
  return $false
}

$RULES = [ordered]@{
  EMAIL    = '[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}'
  PHONE_LK = '(?<![\d.])(?:\+?94|0)[\s-]?7\d[\s-]?\d{3}[\s-]?\d{4}(?!\d|\.\d)'
  NIC_OLD  = '(?<![\w])\d{9}[VvXx](?![\w])'
  NIC_NEW  = '(?<![\d.])(?:19\d{2}|200\d|201[01])(?:[0-3]\d{2}|[5-8]\d{2})0\d{4}(?!\d|\.\d)'
  SECRET   = '(?:AKIA[0-9A-Z]{16}|AIza[0-9A-Za-z_-]{35}|gh[pousr]_[A-Za-z0-9]{36}|github_pat_\w{40,}|sk-(?:ant-)?[A-Za-z0-9_-]{20,}|xox[abprs]-[A-Za-z0-9-]{10,}|-----BEGIN [A-Z ]*PRIVATE KEY-----|(?i:(?:api[_-]?key|secret|token|password)\s*[:=]\s*[''"][^''"\s]{12,}[''"]))'
  ENDPOINT = '(?i:script\.google\.com/macros/s/|hooks\.slack\.com/|discord(?:app)?\.com/api/webhooks/|larksuite\.com/(?:share|base|docx|wiki)|feishu\.cn/|/\.netlify/functions/)'
  BLOB     = '/_blob/[0-9a-f]{16,}'
}
$TEXT = '\.(html?|md|txt|json|js|mjs|css|ps1|ya?ml|svg|xml|csv|tsv|webmanifest|toml|py|sh)$'

# ---------- collect files ----------
$files = @()
if ($Rev) { $files = @(& $Git -C $Root ls-tree -r --name-only $Rev) }
else { $files = @(& $Git -C $Root ls-files) }
$files = @($files | Where-Object { $_ -match $TEXT -and $_ -notlike '.github/leak-guard/*' })

$findings = New-Object System.Collections.Generic.List[string]
function Scan([string]$path, [string[]]$lines) {
  for ($n = 0; $n -lt $lines.Count; $n++) {
    $line = $lines[$n]
    if (-not $line) { continue }
    foreach ($r in $RULES.Keys) {
      foreach ($m in [regex]::Matches($line, $RULES[$r])) {
        if (-not (Allowed $path $r $m.Value)) { $findings.Add("${path}:$($n + 1)  $r  $($m.Value)") }
      }
    }
    if ($deny.Count) {
      $tok = Tokens $line
      foreach ($k in $sizes.Keys) {
        for ($i = 0; $i + $k -le $tok.Count; $i++) {
          $phrase = ($tok[$i..($i + $k - 1)] -join ' ')
          $h = Hash $phrase
          if ($deny.ContainsKey($h)) {
            $rule = "DENY#$($deny[$h])"
            if (-not (Allowed $path $rule $phrase)) { $findings.Add("${path}:$($n + 1)  $rule  $phrase") }
          }
        }
      }
    }
  }
}

foreach ($f in $files) {
  if ($Rev) { $text = (& $Git -C $Root show "${Rev}:$f") -join "`n" }
  else { $p = Join-Path $Root $f; if (-not (Test-Path $p)) { continue }; $text = [IO.File]::ReadAllText($p, $utf8) }
  if ($null -eq $text) { continue }
  Scan $f ($text -split "`r?`n")
}

if ($Messages -and $Messages -notmatch '^0{40}') {
  try { $msg = @(& $Git -C $Root log --format=%B $Messages 2>$null); if ($msg) { Scan '(commit messages)' $msg } } catch {}
}

if ($findings.Count) {
  Write-Host ''
  Write-Host "LEAK CHECK FAILED: $($findings.Count) finding(s)" -ForegroundColor Red
  $findings | Select-Object -Unique | ForEach-Object { Write-Host "  $_" }
  Write-Host ''
  Write-Host 'Remove these, or add a reviewed exception to .github/leak-guard/allow.txt.'
  exit 1
}
Write-Host "Leak check passed ($($files.Count) files scanned)."
exit 0
